from typing import List
class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        # FIX: ties must resolve to the SMALLEST index as well.
        best_i, best_t = events[0][0], events[0][1]
        for j in range(1, len(events)):
            t = events[j][1] - events[j - 1][1]
            if t > best_t or (t == best_t and events[j][0] < best_i):
                best_t, best_i = t, events[j][0]
        return best_i

calculate-digit-sum-of-a-string:
class Solution:
    def digitSum(self, s: str, k: int) -> str:
        # FIX: the driver expects a str; the old code returned int(s), so the
        # judge compared 789 != "789" -> Wrong Answer.
        while len(s) > k:
            s = ''.join(str(sum(int(c) for c in s[i:i + k])) for i in range(0, len(s), k))
        return s

