from typing import List
class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        # FIX: the loop already counts every complementary pair exactly once
        # (it only visits k < 12), so the trailing `// 2` halved the answer.
        from collections import Counter
        c = Counter(h % 24 for h in hours)
        ans = 0
        for k, v in c.items():
            if k in (0, 12):
                ans += v * (v - 1) // 2
            elif k < 12:
                ans += v * c.get(24 - k, 0)
        return ans

